			{ regex: new RegExp(this.getKeywords(inits), 'gm'),			css: 'color3' },		// initializations\r
			{ regex: new RegExp(this.getKeywords(keywords), 'gm'),		css: 'keyword' },		// keywords\r
			{ regex: new RegExp('var', 'gm'),							css: 'variable' },		// variable\r
			{ regex: new RegExp('trace', 'gm'),							css: 'color1' }			// trace\r
